"use client";

import {
  AnimatePresence,
  LayoutGroup,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { AddOnList } from "./checkout-live/add-on-list";
import { priceOrder } from "./checkout-live/data";
import { OrderSummary } from "./checkout-live/order-summary";
import { PaymentFields } from "./checkout-live/payment-fields";
import { PlanRadios } from "./checkout-live/plan-radios";
import { BillingToggle } from "./shared/billing-toggle";
import { type PayState } from "./shared/pay-button";
import { type Billing, type PlanId, PLANS } from "./shared/plans";
import { Stepper } from "./shared/stepper";

// One position spring carries the summary to the centre once the payment lands.
const GLIDE: Transition = {
  type: "spring",
  stiffness: 260,
  damping: 32,
  mass: 1,
};
const FADE: Transition = { duration: 0.25 };
const INSTANT: Transition = { duration: 0 };

const MAX_SEATS = 60;

/**
 * A subscription checkout for Fernhill. Every edit to the plan, billing
 * period, seats, add-ons or coupon recomputes the summary beside it. Paying
 * fades the form aside and the summary glides to the centre as a receipt.
 * It is a demo: it takes no card number and sends nothing anywhere.
 */
export function CheckoutLive({ className }: { className?: string }) {
  const titleId = useId();
  const planName = useId();
  const reduceMotion = useReducedMotion();
  const [billing, setBilling] = useState<Billing>("yearly");
  const [planId, setPlanId] = useState<PlanId>("practice");
  const [seats, setSeats] = useState(8);
  const [addOns, setAddOns] = useState<string[]>(["support"]);
  const [coupon, setCoupon] = useState(false);
  const [pay, setPay] = useState<PayState>("idle");
  const timer = useRef<number | undefined>(undefined);
  // The pay button leaves with the form, so focus moves to the receipt's own button.
  const again = useRef<HTMLButtonElement | null>(null);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const plan = PLANS.find((item) => item.id === planId) ?? PLANS[1]!;
  const seatMax = plan.seatLimit ?? MAX_SEATS;
  const order = priceOrder(plan, seats, billing, addOns, coupon);
  const paid = pay === "paid";
  useEffect(() => {
    if (paid) again.current?.focus({ preventScroll: true });
  }, [paid]);

  const choosePlan = (next: PlanId) => {
    setPlanId(next);
    const limit = PLANS.find((item) => item.id === next)?.seatLimit;
    if (limit) setSeats((count) => Math.min(count, limit));
  };

  const startPayment = () => {
    setPay("processing");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setPay("paid"), 1500);
  };

  const reset = () => {
    setPay("idle");
    setCoupon(false);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <h2 id={titleId} className="sr-only">
        Fernhill checkout
      </h2>
      <LayoutGroup>
        <div
          className={cn(
            "grid gap-6 p-5 @2xl:p-8",
            paid ? "justify-items-center" : "@4xl:grid-cols-[1fr_22rem]",
          )}
        >
          <AnimatePresence mode="popLayout" initial={false}>
            {paid ? null : (
              <motion.div
                key="form"
                exit={{ opacity: 0, x: "-2rem" }}
                transition={reduceMotion ? INSTANT : FADE}
                className="flex min-w-0 flex-col gap-6"
              >
                <div className="grid gap-2 @md:grid-cols-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="lg"
                    onClick={startPayment}
                    disabled={pay === "processing"}
                  >
                    Pay with your wallet
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="lg"
                    onClick={startPayment}
                    disabled={pay === "processing"}
                  >
                    Pay from your bank
                  </Button>
                </div>
                <p className="flex items-center gap-3 text-xs text-muted-foreground">
                  <span aria-hidden="true" className="h-px flex-1 bg-border" />
                  Or pay with a saved card
                  <span aria-hidden="true" className="h-px flex-1 bg-border" />
                </p>

                <section
                  className="flex flex-col gap-3"
                  aria-labelledby={`${titleId}-plan`}
                >
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <h3 id={`${titleId}-plan`} className="text-sm font-medium">
                      Plan
                    </h3>
                    <BillingToggle value={billing} onValueChange={setBilling} />
                  </div>
                  <PlanRadios
                    name={planName}
                    value={planId}
                    onValueChange={choosePlan}
                    billing={billing}
                  />
                  <div className="flex items-center justify-between gap-3 rounded-xl border border-border px-3 py-2">
                    <span className="text-sm">
                      Practitioner seats
                      <span className="block text-xs text-muted-foreground">
                        {plan.seatLimit
                          ? `${plan.name} holds up to ${plan.seatLimit}`
                          : "No limit on this plan"}
                      </span>
                    </span>
                    <Stepper
                      label="Practitioner seats"
                      unit="seats"
                      value={seats}
                      onValueChange={setSeats}
                      min={1}
                      max={seatMax}
                    />
                  </div>
                </section>

                <AddOnList
                  value={addOns}
                  onToggle={(id, on) =>
                    setAddOns((list) =>
                      on ? [...list, id] : list.filter((item) => item !== id),
                    )
                  }
                />

                <PaymentFields
                  pay={pay}
                  amount={order.due}
                  onPay={startPayment}
                />
              </motion.div>
            )}
          </AnimatePresence>

          <motion.aside
            layout={!reduceMotion}
            transition={GLIDE}
            aria-label="Order summary"
            className={cn(
              "w-full self-start rounded-2xl border border-border bg-background p-5",
              paid && "max-w-md",
            )}
          >
            <OrderSummary
              order={order}
              coupon={coupon}
              onCoupon={setCoupon}
              paid={paid}
            />
            {paid ? (
              <Button
                ref={again}
                type="button"
                variant="outline"
                className="mt-5 w-full"
                onClick={reset}
              >
                Start the demo again
              </Button>
            ) : null}
          </motion.aside>
        </div>
      </LayoutGroup>
      <p aria-live="polite" className="sr-only">
        {pay === "processing"
          ? "Processing the payment."
          : paid
            ? "Payment received. The summary is now your receipt."
            : ""}
      </p>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { useId } from "react";

import { Checkbox } from "@/components/ui/checkbox";

import { ADD_ONS } from "./data";

/** Props for the add-on list. */
export interface AddOnListProps {
  value: string[];
  onToggle: (id: string, on: boolean) => void;
}

/**
 * The optional extras, each a checkbox with its price and what it adds.
 * Space toggles the focused one.
 */
export function AddOnList({ value, onToggle }: AddOnListProps) {
  const id = useId();
  return (
    <fieldset>
      <legend className="mb-2 text-sm font-medium">Add-ons</legend>
      <div className="flex flex-col gap-1 rounded-xl border border-border py-1">
        {ADD_ONS.map((item) => {
          const inputId = `${id}-${item.id}`;
          return (
            <div
              key={item.id}
              className="flex items-center gap-3 px-3 py-2 text-sm"
            >
              <Checkbox
                id={inputId}
                checked={value.includes(item.id)}
                onCheckedChange={(on) => onToggle(item.id, on === true)}
              />
              <label
                htmlFor={inputId}
                className="flex min-w-0 flex-1 cursor-pointer flex-col"
              >
                <span className="font-medium">{item.name}</span>
                <span className="text-xs text-muted-foreground">
                  {item.detail}
                </span>
              </label>
              <span className="shrink-0 tabular-nums">
                ${item.monthly}
                <span className="text-xs text-muted-foreground"> a month</span>
              </span>
            </div>
          );
        })}
      </div>
    </fieldset>
  );
}

import { plural } from "../shared/money";
import { type Billing, type Plan, seatPriceFor } from "../shared/plans";

/** An optional extra a clinic can add to its plan. */
export interface AddOn {
  id: string;
  name: string;
  detail: string;
  /** The price for one month. */
  monthly: number;
}

/** The add-ons on offer. */
export const ADD_ONS: AddOn[] = [
  {
    id: "texts",
    name: "Reminder text pack",
    detail: "2,000 more texts a month",
    monthly: 29,
  },
  {
    id: "rooms",
    name: "Extra room calendars",
    detail: "Four more rooms to book",
    monthly: 15,
  },
  {
    id: "support",
    name: "Priority support",
    detail: "Answers within two hours",
    monthly: 49,
  },
];

/** The one coupon the demo accepts, and what it takes off. */
export const COUPON = {
  code: "FERNHILL10",
  share: 0.1,
  reason: "10% off for clinics moving from paper",
};

/** The sales tax rate for the clinic's address. */
export const TAX_RATE = 0.08;

/** One line of the order, with how its amount was worked out. */
export interface OrderLine {
  id: string;
  label: string;
  how: string;
  amount: number;
}

/** The whole order: its lines, the discount, tax and the amount due today. */
export interface Order {
  lines: OrderLine[];
  subtotal: number;
  discount: number;
  tax: number;
  due: number;
}

/** Works the order out from every choice on the form. Yearly billing charges twelve months today. */
export function priceOrder(
  plan: Plan,
  seats: number,
  billing: Billing,
  addOns: string[],
  coupon: boolean,
): Order {
  const months = billing === "yearly" ? 12 : 1;
  const perSeat = seatPriceFor(plan, billing);
  const span = billing === "yearly" ? " for 12 months" : "";
  const lines: OrderLine[] = [
    {
      id: "plan",
      label: `${plan.name} plan`,
      how: `${plural(seats, "seat")} at $${perSeat.toFixed(2)}${span}`,
      amount: perSeat * seats * months,
    },
    ...ADD_ONS.filter((item) => addOns.includes(item.id)).map((item) => ({
      id: item.id,
      label: item.name,
      how:
        billing === "yearly"
          ? `$${item.monthly} a month for 12 months`
          : "Billed every month",
      amount: item.monthly * months,
    })),
  ];
  const subtotal = lines.reduce((sum, line) => sum + line.amount, 0);
  const discount = coupon ? subtotal * COUPON.share : 0;
  const tax = (subtotal - discount) * TAX_RATE;
  return { lines, subtotal, discount, tax, due: subtotal - discount + tax };
}

const CENTS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const DOLLARS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

/** Rounds an amount to whole cents, so every line of a sum adds up to the shown total. */
export const toCents = (value: number) => Math.round(value * 100) / 100;

/** A dollar amount with cents, such as $1,843.20. */
export const formatCents = (value: number) => CENTS.format(toCents(value));

/** A dollar amount with no cents, such as $240. */
export const formatDollars = (value: number) =>
  DOLLARS.format(Math.round(value));

/** A whole number with thousands separators, such as 12,000. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** A price that may need cents: $24 stays whole, $19.20 keeps its cents. */
export const formatPrice = (value: number) =>
  Number.isInteger(toCents(value)) ? formatDollars(value) : formatCents(value);

/** Writes a count with its noun, such as "1 seat" or "12 seats". */
export const plural = (count: number, one: string, many = `${one}s`) =>
  `${formatCount(count)} ${count === 1 ? one : many}`;

/** How often a clinic pays. */
export type Billing = "monthly" | "yearly";

/** The three Fernhill plans, smallest first. */
export type PlanId = "solo" | "practice" | "group";

/** One Fernhill plan and what it includes. */
export interface Plan {
  id: PlanId;
  name: string;
  /** Who the plan is for, in a few words. */
  audience: string;
  /** The price of one practitioner seat for one month, billed monthly. */
  seatPrice: number;
  /** The most practitioners the plan holds, or null for no limit. */
  seatLimit: number | null;
  /** Bookings a month the plan includes before each extra booking costs more. */
  bookingsIncluded: number;
}

/** Yearly billing takes this share off every price. */
export const YEARLY_SAVING = 0.2;

/** The cost of each booking past a plan's included amount. */
export const EXTRA_BOOKING_PRICE = 0.03;

/** The plans in size order. */
export const PLANS: Plan[] = [
  {
    id: "solo",
    name: "Solo",
    audience: "One room, a few practitioners",
    seatPrice: 14,
    seatLimit: 3,
    bookingsIncluded: 1_000,
  },
  {
    id: "practice",
    name: "Practice",
    audience: "A busy clinic with a front desk",
    seatPrice: 24,
    seatLimit: 25,
    bookingsIncluded: 10_000,
  },
  {
    id: "group",
    name: "Group",
    audience: "Several clinics under one roof",
    seatPrice: 38,
    seatLimit: null,
    bookingsIncluded: 50_000,
  },
];

/** The price of one seat for one month under a billing period. */
export const seatPriceFor = (plan: Plan, billing: Billing) =>
  billing === "yearly" ? plan.seatPrice * (1 - YEARLY_SAVING) : plan.seatPrice;

/** True when the plan has room for this many practitioners. */
export const holdsSeats = (plan: Plan, seats: number) =>
  plan.seatLimit === null || seats <= plan.seatLimit;

/** The smallest plan that has room for this many practitioners. */
export const smallestPlanFor = (seats: number) =>
  PLANS.find((plan) => holdsSeats(plan, seats)) ?? PLANS[PLANS.length - 1]!;

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

import { CircleCheckIcon, PlusIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";

import { formatCents } from "../shared/money";
import { PromoField } from "../shared/promo-field";
import { Reveal } from "../shared/reveal";
import { COUPON, type Order, TAX_RATE } from "./data";

const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for the order summary. */
export interface OrderSummaryProps {
  order: Order;
  coupon: boolean;
  onCoupon: (on: boolean) => void;
  /** Turns the summary into a receipt: the coupon link hides and the paid header opens. */
  paid: boolean;
}

/**
 * Lists each line of the order with how it was worked out, a link that opens
 * the coupon field, then the subtotal, tax and amount due. Every amount rolls,
 * and lines open and close their height as the form changes.
 */
export function OrderSummary({
  order,
  coupon,
  onCoupon,
  paid,
}: OrderSummaryProps) {
  const reduceMotion = useReducedMotion();
  const [couponOpen, setCouponOpen] = useState(false);
  const transition = reduceMotion ? INSTANT : HEIGHT;
  // Escape closes the field and hands focus back to the link that opened it.
  const link = useRef<HTMLButtonElement | null>(null);
  const backToLink = useRef(false);
  useEffect(() => {
    if (!couponOpen && backToLink.current) {
      backToLink.current = false;
      link.current?.focus();
    }
  }, [couponOpen]);

  return (
    <div className="flex flex-col gap-4">
      <Reveal show={paid}>
        <div className="flex flex-col items-center gap-2 pb-2 text-center">
          <CircleCheckIcon
            aria-hidden="true"
            className="size-10 text-marketing-green-ink"
          />
          <p className="text-lg font-semibold">Payment received</p>
          <p className="text-sm text-muted-foreground">
            Receipt FH-20418, paid with Visa ending 4242 on Nov 11, 2026.
          </p>
        </div>
      </Reveal>

      <h3 className="text-base font-semibold">
        {paid ? "Receipt" : "Order summary"}
      </h3>

      <ul className="flex flex-col text-sm">
        <AnimatePresence initial={false}>
          {order.lines.map((line) => (
            <motion.li
              key={line.id}
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={transition}
              className="overflow-hidden"
            >
              <div className="flex justify-between gap-4 border-b border-border py-2.5">
                <span className="min-w-0">
                  <span className="block font-medium">{line.label}</span>
                  <span className="block text-xs text-muted-foreground">
                    {line.how}
                  </span>
                </span>
                <RollingText
                  text={formatCents(line.amount)}
                  className="self-start"
                />
              </div>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>

      {paid ? null : coupon || couponOpen ? (
        <PromoField
          applied={coupon ? COUPON.code : null}
          autoFocus
          hint={`Try ${COUPON.code}. Escape closes the field.`}
          onApply={(typed) => {
            const ok = typed.trim().toUpperCase() === COUPON.code;
            if (ok) onCoupon(true);
            return ok;
          }}
          onRemove={() => onCoupon(false)}
          onEscape={() => {
            if (coupon) return;
            backToLink.current = true;
            setCouponOpen(false);
          }}
        />
      ) : (
        <Button
          ref={link}
          type="button"
          variant="ghost"
          size="sm"
          className="self-start"
          onClick={() => setCouponOpen(true)}
        >
          <PlusIcon aria-hidden="true" />
          Add a coupon
        </Button>
      )}

      <dl className="flex flex-col text-sm">
        <div className="flex justify-between gap-4 py-1.5">
          <dt className="text-muted-foreground">Subtotal</dt>
          <dd>
            <RollingText text={formatCents(order.subtotal)} />
          </dd>
        </div>
        <Reveal show={order.discount > 0}>
          <div className="flex justify-between gap-4 py-1.5">
            <dt className="min-w-0 text-muted-foreground">{COUPON.reason}</dt>
            <dd className="text-marketing-green-ink">
              <RollingText text={`-${formatCents(order.discount)}`} />
            </dd>
          </div>
        </Reveal>
        <div className="flex justify-between gap-4 py-1.5">
          <dt className="text-muted-foreground">
            Sales tax, {Math.round(TAX_RATE * 100)}%
          </dt>
          <dd>
            <RollingText text={formatCents(order.tax)} />
          </dd>
        </div>
        <div className="mt-2 flex items-baseline justify-between gap-4 border-t border-border pt-3">
          <dt className="font-medium">{paid ? "Paid today" : "Due today"}</dt>
          <dd className="text-2xl font-semibold tracking-tight">
            <RollingText text={formatCents(order.due)} />
          </dd>
        </div>
      </dl>
    </div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
