/** Where a payment stands. */
export type PayState = "idle" | "processing" | "paid" | "failed";

const SWAP: Transition = { duration: 0.18, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

/** Props for the pay button. */
export interface PayButtonProps {
  state: PayState;
  amount: number;
  onPay: () => void;
  className?: string;
}

/**
 * The button that pays an amount. Its icon and label change with the state:
 * a lock and the amount, a spinner while processing, a check once paid, and
 * a cross with a retry after a decline. The amount rolls when it changes.
 */
export function PayButton({ state, amount, onPay, className }: PayButtonProps) {
  const reduceMotion = useReducedMotion();
  const busy = state === "processing" || state === "paid";
  return (
    <Button
      type="button"
      size="lg"
      variant={state === "failed" ? "destructive" : "default"}
      aria-disabled={busy}
      onClick={() => {
        if (!busy) onPay();
      }}
      className={cn(
        "w-full overflow-hidden",
        busy && "cursor-default",
        className,
      )}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={state}
          initial={{ opacity: 0, y: "70%" }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: "-70%" }}
          transition={reduceMotion ? INSTANT : SWAP}
          className="inline-flex items-center gap-2"
        >
          {state === "idle" ? (
            <>
              <LockIcon aria-hidden="true" />
              Pay <RollingText text={formatCents(amount)} />
            </>
          ) : null}
          {state === "processing" ? (
            <>
              <LoaderIcon
                aria-hidden="true"
                className="motion-safe:animate-spin"
              />
              Processing
            </>
          ) : null}
          {state === "paid" ? (
            <>
              <CheckIcon aria-hidden="true" />
              Paid {formatCents(amount)}
            </>
          ) : null}
          {state === "failed" ? (
            <>
              <XIcon aria-hidden="true" />
              Declined, try again
            </>
          ) : null}
        </motion.span>
      </AnimatePresence>
    </Button>
  );
}

